import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.DQQHyi2x.js";const x=JSON.parse('{"title":"Codex Backup/Export/Restore Policy","description":"","frontmatter":{},"headers":[],"relativePath":"plans/2026-05-26-codex-backup-restore-policy.md","filePath":"plans/2026-05-26-codex-backup-restore-policy.md"}'),i={name:"plans/2026-05-26-codex-backup-restore-policy.md"};function l(s,e,c,d,n,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="codex-backup-export-restore-policy" tabindex="-1">Codex Backup/Export/Restore Policy <a class="header-anchor" href="#codex-backup-export-restore-policy" aria-label="Permalink to &quot;Codex Backup/Export/Restore Policy&quot;">​</a></h1><p>Date: 2026-05-26 Issue: #142</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Codex backups are export-only. Claude Deck may create and download a redacted Codex export, but it must not automatically restore Codex files until there is a stable provider-owned restore path.</p><h2 id="export-scope" tabindex="-1">Export Scope <a class="header-anchor" href="#export-scope" aria-label="Permalink to &quot;Export Scope&quot;">​</a></h2><p>Codex exports include:</p><ul><li><code>config.toml</code> with secret-like assignments redacted</li><li><code>*.config.toml</code> profile files with secret-like assignments redacted</li><li><code>rules/*.rules</code> files with secret-like assignments redacted</li><li>redacted provider inventory metadata</li></ul><p>Codex exports exclude:</p><ul><li><code>auth.json</code></li><li><code>history.jsonl</code></li><li><code>models_cache.json</code></li><li><code>*.sqlite</code> files and related SQLite sidecars</li><li>raw cache payloads and prompt text</li></ul><h2 id="restore-policy" tabindex="-1">Restore Policy <a class="header-anchor" href="#restore-policy" aria-label="Permalink to &quot;Restore Policy&quot;">​</a></h2><p>Automatic Codex restore is refused with an explicit error. The restore plan lists the archive contents for review, but the restore action returns a refusal instead of extracting files.</p><p>Refusal reasons:</p><ul><li>Codex auth, history, cache, and local state are intentionally excluded from exports.</li><li>Automatic restore could overwrite active Codex state without a stable provider-owned restore API.</li></ul><p>Manual restore remains possible outside Claude Deck after downloading and reviewing the redacted archive.</p>',14)])])}const h=o(i,[["render",l]]);export{x as __pageData,h as default};
